		<div class="elementor-element elementor-element-4113aed e-flex e-con-boxed e-con e-child" data-id="4113aed" data-element_type="container" data-settings="{&quot;background_background&quot;:&quot;classic&quot;,&quot;jet_parallax_layout_list&quot;:[]}">
